// Maps file and folder names to FDO's own icons (src/assets/icons/files,
// generated by scripts/generate-file-icons.cjs).
const BY_NAME = {
    'package.json': 'package',
    'package-lock.json': 'lock', 'yarn.lock': 'lock', 'pnpm-lock.yaml': 'lock',
    'license': 'license', 'license.md': 'license', 'license.txt': 'license', 'copying': 'license',
    'dockerfile': 'docker', '.dockerignore': 'docker',
    '.gitignore': 'git', '.gitattributes': 'git', '.gitmodules': 'git',
    '.npmrc': 'config', '.editorconfig': 'config', '.prettierrc': 'config', '.eslintrc': 'config',
};

const BY_EXTENSION = {
    js: 'js', mjs: 'js', cjs: 'js', jsx: 'jsx', ts: 'ts', mts: 'ts', cts: 'ts', tsx: 'tsx',
    json: 'json', jsonc: 'json', json5: 'json', md: 'md', mdx: 'md', markdown: 'md',
    css: 'css', scss: 'scss', sass: 'scss', less: 'css', html: 'html', htm: 'html',
    yml: 'yaml', yaml: 'yaml', xml: 'xml', svg: 'svg',
    png: 'image', jpg: 'image', jpeg: 'image', gif: 'image', webp: 'image', ico: 'image', bmp: 'image', avif: 'image',
    txt: 'text', log: 'text', sh: 'shell', bash: 'shell', zsh: 'shell', env: 'env',
    lock: 'lock', toml: 'config', ini: 'config', conf: 'config', cfg: 'config', sql: 'sql', py: 'python',
    woff: 'font', woff2: 'font', ttf: 'font', otf: 'font', eot: 'font',
    zip: 'archive', tar: 'archive', gz: 'archive', tgz: 'archive', wasm: 'wasm',
};

const FOLDERS = {
    src: 'src', source: 'src', lib: 'src', app: 'src', components: 'src',
    dist: 'dist', build: 'dist', out: 'dist', release: 'dist',
    node_modules: 'node',
    test: 'test', tests: 'test', __tests__: 'test', spec: 'test', e2e: 'test',
    docs: 'docs', doc: 'docs', documentation: 'docs',
    '.git': 'git', '.github': 'git',
    assets: 'assets', images: 'assets', img: 'assets', static: 'assets', public: 'assets',
};

const base = name => String(name ?? '').split('/').pop().toLowerCase();

export function getIconForFile(name) {
    const file = base(name);
    if (BY_NAME[file]) return `file_${BY_NAME[file]}.svg`;
    if (file.startsWith('.env')) return 'file_env.svg';
    if (/^tsconfig.*\.json$|^jsconfig.*\.json$/.test(file)) return 'file_config.svg';
    if (/^readme/.test(file)) return 'file_md.svg';
    const extension = file.includes('.') ? file.slice(file.lastIndexOf('.') + 1) : '';
    return `file_${BY_EXTENSION[extension] || 'default'}.svg`;
}

export function getIconForFolder(name) {
    return `folder_${FOLDERS[base(name)] || 'default'}.svg`;
}

export function getIconForOpenFolder(name) {
    return getIconForFolder(name).replace(/\.svg$/, '_opened.svg');
}
